$ec_lang['ip_du_estimate']='Ukaguzi wa usawa, q<sub>last</sub>/q<sub>avg,field</sub> <span title="Mtiririko uliokokotolewa wa kituo cha mwisho cha maji ukigawanywa kwa kadirio la wastani wa mtiririko wa kituo cha maji shambani &mdash; hii ni kadirio la usawa wa usambazaji wa robo ya chini wa kawaida (wastani wa kundi la chini &divide; wastani wa jumla wa watu wote); hii inatokana na sampuli ndogo iliyoigwa na masahihisho yaliyokadiriwa na mtumiaji badala ya sampuli kamili ya kitakwimu ya shamba zima. Thamani sawa na au zaidi ya 1 zinawezekana na ni sahihi: zinamaanisha tu kwamba shinikizo la kituo cha mwisho cha maji liko sawa na au juu ya wastani wa shambani uliokadiriwa, hivyo kituo kingine cha maji ndicho chenye shinikizo la chini kabisa. Hili linaweza kuwa kwa sababu kituo cha mwisho cha maji kiko mahali pa chini, au kwa sababu kadirio la &Delta;shinikizo ni dogo mno." class="ec-tip">?</span>';
